cd /var/folders/8z/mc_hxmwj0nj_4syjvxt85z200000gn/T/flow-eval-fixture-tmB3Pi/repo && mkdir -p .flow-tmp && printf '%s\n' '{"active": true, "ran": false, "reason": "not-researchable"}' > .flow-tmp/research-status.json && cat > .flow-tmp/excluded-paths.json <<'EOF'
{"version": 1, "excluded": [
  {"id": "dynamodb-streams-trigger", "path": "Trigger section generation from a DynamoDB Streams event on the reports table instead of a queue", "reason": "A stream shard processes records in order and a failing record blocks its shard until retries run out, so one 60-second failing paid call stalls every report behind it; SQS gives per-message retry and a dead-letter queue (flow-system-design aws.md SQS + Lambda)."},
  {"id": "lambda-async-self-invoke", "path": "Have the POST handler invoke the worker Lambda asynchronously, one event per section", "reason": "Lambda async invocation retries twice on its own and discards failed events without a configured destination, and it can deliver the same event twice; flow-system-design aws.md says to prefer SQS when retry, rate and dead-letter control are needed."},
  {"id": "usage-plan-as-spend-cap", "path": "Use an API Gateway usage plan quota and API keys as the spend cap and caller gate for POST /reports", "reason": "AWS states usage plan throttling and quotas are best-effort, clients can exceed them, and they must not be relied on to control costs, and that API keys must not be used for authorization (https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-api-usage-plans.html)."}
]}
EOF
jq . .flow-tmp/excluded-paths.json >/dev/null && echo ok
